'use strict';
const $=s=>document.querySelector(s),escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const role=location.pathname==='/host'?'host':location.pathname==='/display'?'display':'team';document.body.classList.toggle('display',role==='display');
/* 0.14: /host?spel=quiz|buzzer|wordrace|city kiest vooraf de juiste spelvorm (knop 'Spel openen' in de app). */
const presetMode=(()=>{const v=new URLSearchParams(location.search).get('spel');return ['quiz','buzzer','wordrace','city'].includes(v)?v:'';})();
let state=null,hostKey='',teamKey=new URLSearchParams(location.search).has('new')?'':localStorage.getItem('groepsspel-lan-team')||'',urls=[],signature='',connected=false,polling=false,offset=0,latency=null,busy=false,flushing=false,dbPromise,photos={},drafts=presetMode?{setupMode:presetMode}:{},photoURLs={};
const sessionKey=()=>state?state.room_id+':'+state.me?.id:'';
function note(text){$('#notice').textContent=text;$('#notice').style.display='block';clearTimeout(note.timer);note.timer=setTimeout(()=>$('#notice').style.display='none',6000);}
function auth(){return role==='host'?hostKey:teamKey;}
async function api(path,body,token=auth()){const response=await fetch(path,{method:body?'POST':'GET',headers:{...(token?{Authorization:'Bearer '+token}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});const data=await response.json();if(!response.ok){const err=new Error(data.error||'Verzoek mislukt.');err.status=response.status;throw err;}return data;}
function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('groepsspel-lan-outbox',1);req.onupgradeneeded=()=>req.result.createObjectStore('items',{keyPath:'key'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});return dbPromise;}
async function outbox(action,item){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('items',action==='all'?'readonly':'readwrite'),store=tx.objectStore('items');let req=action==='all'?store.getAll():action==='put'?store.put(item):store.delete(item);tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Opslaan afgebroken.'));});}
function preserveRender(){document.querySelectorAll('[data-draft]').forEach(e=>drafts[e.id]=e.value);const active=document.activeElement?.id,selection=document.activeElement?.selectionStart;render();document.querySelectorAll('[data-draft]').forEach(e=>{if(Object.hasOwn(drafts,e.id))e.value=drafts[e.id];});if(active){const input=document.getElementById(active);input?.focus();if(typeof selection==='number'&&input?.setSelectionRange)try{input.setSelectionRange(selection,selection);}catch{}}clock();}
function scores(){return `<div class="scores">${(state?.teams||[]).map(t=>`<div class="score">${escapeHtml(t.name)}<b>${t.score}</b>${t.spectator?'<small>Toeschouwer</small>':''}</div>`).join('')}</div>`;}
const evidenceMode = () => state?.evidence?.mode || 'app';
const evidenceLink = () => state?.evidence?.link || '';
function evidenceCityHost() {
  const e=state.evidence||{mode:'app',link:''};
  const mode=drafts.evidenceMode ?? e.mode;
  const link=drafts.evidenceLink ?? e.link;
  return `<section class="panel evidence-panel"><h2>Bewijs & communicatie · Stadskwis</h2>
    <p>Optioneel bewijs delen via WhatsApp. De groep maak je zelf aan; beoordeling en punten blijven in Groepsspel.</p>
    <label class="field"><span>Bewijs inleveren via</span><select id="evidenceMode" data-draft><option value="app" ${mode==='app'?'selected':''}>Groepsspel</option><option value="whatsapp" ${mode==='whatsapp'?'selected':''}>WhatsApp</option><option value="both" ${mode==='both'?'selected':''}>Beide</option></select></label>
    ${mode !== 'app' ? `<label class="field"><span>WhatsApp-groepsuitnodiging</span><input id="evidenceLink" data-draft type="url" placeholder="https://chat.whatsapp.com/..." maxlength="220" value="${escapeHtml(link)}"></label>` : ''}
    <p class="tiny">Deelnemers zien elkaars telefoonnummers in WhatsApp. De foto's staan niet automatisch in Groepsspel of op het scorebord.</p>
    ${button('Bewijskanaal opslaan','evidence_save','','secondary')}
    ${e.mode!=='app'&&e.link?`<a href="${escapeHtml(e.link)}" target="_blank" rel="noopener noreferrer">Open WhatsApp-groep ↗</a> ${qr(e.link)}`:''}</section>`;
}
function evidenceCityTeam(){const e=state?.evidence||{};return e.mode==='whatsapp'||e.mode==='both'?`<section class="panel evidence-panel"><h3>Bewijs via WhatsApp</h3><p>Stuur je foto in de groepschat met <b>teamnaam en opdracht</b>. Meld het bewijs daarna hieronder aan zodat de spelleider punten kan geven.</p><a class="btn secondary" href="${escapeHtml(e.link)}" target="_blank" rel="noopener noreferrer">Open WhatsApp-groep ↗</a><p class="tiny">De spelleider beoordeelt handmatig; telefoonnummers zijn in de groep zichtbaar. WhatsApp heeft internet nodig.</p></section>`:'';}
const button=(label,action,extra='',secondary=false)=>`<button type="button" data-action="${action}" class="${secondary?'secondary':''}" ${extra}>${label}</button>`;
function qr(url){try{const code=qrcode(0,'M');code.addData(url);code.make();return `<div class="qr">${code.createImgTag(4,12,'QR-code om mee te doen')}</div>`;}catch{return'';}}
function answerText(q){return q.options?'ABCD'[q.correct]+'. '+q.options[q.correct]:(q.answers||[]).join(' / ');}
function question(){if(state.mode==='wordrace')return wordRace();if(state.auto)return autoScreen();const q=state.question;if(!q)return `<h2>${state.phase==='finished'?'Spel afgerond':state.phase==='countdown'?'De volgende vraag komt eraan':'Wacht op de spelleider'}</h2>`;return `<p class="counter">Vraag ${state.index+1} / ${state.total} · ${escapeHtml(q.category||'Quiz')}</p><h1 class="question">${escapeHtml(q.q)}</h1><div class="options">${(q.options||[]).map((a,i)=>`<div class="option ${state.phase==='reveal'&&q.correct===i?'correct':''}"><b>${'ABCD'[i]}</b>${escapeHtml(a)}</div>`).join('')}</div>${state.phase==='reveal'&&q.kind==='text'?`<div class="banner">Juiste antwoord: ${escapeHtml(answerText(q))}</div>`:''}`;}
/* 0.15.3: het gekozen wifi-adres blijft staan (voorheen sprong het bij iedere verversing terug naar het eerste). */
let lanPick=(()=>{try{return localStorage.getItem('groepsspel-lan-address')||'';}catch{return '';}})();
const lanURL=()=>urls.includes(lanPick)?lanPick:(urls[0]||'');
function host(){const playing=!['lobby','finished'].includes(state.phase),activeTeams=state.teams.filter(t=>!t.spectator),first=state.buzzes[0];return `<div class="grid"><section class="panel"><h1>${escapeHtml(state.name)}</h1><p>Spelleider · lokale server op deze pc</p><p class="code">${state.code}</p><label class="field"><span>Adres voor teamtelefoons (dezelfde wifi)</span><select id="lanAddress">${urls.map(u=>`<option value="${escapeHtml(u)}" ${u===lanURL()?'selected':''}>${escapeHtml(u)}</option>`).join('')}</select></label>${urls.length>1?'<p class="tiny">Meerdere adressen gevonden. Kan een telefoon niet verbinden? Kies hier een ander adres en laat opnieuw scannen.</p>':''}<div id="joinQR">${lanURL()?qr(lanURL()+'/team?code='+state.code):''}</div><p id="joinURL" class="linkline">${lanURL()?escapeHtml(lanURL()+'/team?code='+state.code):'Geen netwerkadres gevonden'}</p><div class="actions"><a class="btn secondary" href="/display" target="_blank" rel="noopener">Open beamerweergave ↗</a><button type="button" class="secondary" data-open-tv>📺 TV-scherm</button>${button('Download uitslag','export','',true)}</div><p class="tiny">Gebruik een privé-wifinetwerk waarop apparaten elkaar kunnen bereiken. Houd deze pc en dit venster actief. Internet is voor het spel niet nodig.</p></section><section class="panel"><h2>Teams & verbinding</h2>${state.teams.length?state.teams.map(t=>`<div class="teamline"><span class="status ${t.connected?'':'bad'}">${t.connected?'●':'○'}</span><strong>${escapeHtml(t.name)}</strong><small>${t.connected?'Verbonden':'Niet verbonden'}</small>${button(t.spectator?'Meespelen':'Toeschouwer','spectator',`data-id="${t.id}" data-value="${!t.spectator}"`,true)}${button('Score','score',`data-id="${t.id}" data-name="${escapeHtml(t.name)}"`,true)}${!playing?button('Verwijder','remove_team',`data-id="${t.id}"`,true):''}</div>`).join(''):'<p>Laat teams de QR-code scannen. Minimaal twee teams voor een quiz; één of meer teams voor de stadskwis.</p>'}<p class="tiny">De ronde pauzeert bij verbindingsverlies. Een afwezig team kun je tijdelijk op toeschouwer zetten.</p></section></div>${state.mode==='city' ? evidenceCityHost() : ''}${!playing?`<section class="panel"><h2>Spel klaarzetten</h2><form id="setupForm"><div class="grid"><label class="field"><span>Spelnaam</span><input id="setupName" data-draft name="name" value="${escapeHtml(state.name)}" maxlength="80" required></label><label class="field"><span>Spelvorm</span><select id="setupMode" data-draft name="mode"><option value="buzzer">Buzzerquiz</option><option value="quiz">Pubquiz / persoonlijke quiz · telefoonantwoorden</option><option value="wordrace">Halve Minuut · geheime woorden</option><option value="city">Stadskwis / dorpskwis</option></select></label><label class="field"><span>Taal van het vragenpakket</span><select id="setupLanguage" data-draft name="language">${Object.entries({nl:'Nederlands',en:'English',de:'Deutsch',fr:'Français',es:'Español',it:'Italiano'}).map(([v,n])=>`<option value="${v}">${n} · ${state.packs[v]||0} vragen</option>`).join('')}</select></label><label class="field"><span>Aantal vragen</span><input id="setupCount" data-draft name="count" type="number" min="1" max="200" value="20" required></label><label class="field"><span>Onderwerp (Nederlands)</span><select id="setupTopic" data-draft name="topic"><option value="all">Alle onderwerpen</option>${(state.topics||[]).map(t=>`<option value="${escapeHtml(t)}">${escapeHtml(t)}</option>`).join('')}</select></label><label class="field"><span>Presentator (Buzzerquiz)</span><select id="setupAuto" data-draft name="auto"><option value="1">Automatisch · het spel presenteert zelf</option><option value="0">Ik presenteer zelf</option></select></label><label class="field"><span>Show (automatisch)</span><select id="setupShow" data-draft name="show"><option value="normaal">Normaal · 5 rondes</option><option value="kort">Kort · 3 rondes</option><option value="lang">Lang · 7 rondes met buzzerrace en de bom</option></select></label><label class="field"><span>Antwoordtijd pubquiz (seconden)</span><input id="setupSeconds" data-draft name="seconds" type="number" min="5" max="180" value="30" required></label></div><details><summary>Eigen vragen invoeren (optioneel)</summary><p class="tiny">Importeer jullie persoonlijke vragenbestand, of voer een JSON-lijst in. Open vraag: q en answer (of answers voor meerdere schrijfwijzen). Meerkeuze: q, vier options en correct (0–3). Leeg laten voor het taalpakket. Hoofdletters en accenten tellen niet mee; andere schrijfwijzen geef je vooraf op.</p><label class="field">Vragenbestand importeren<input type="file" id="questionsImport" accept=".json,application/json"></label><textarea id="questionJSON" class="edit-json" data-draft placeholder='[{"q":"Jullie vraag?","options":["A","B","C","D"],"correct":0}]'></textarea></details><details><summary>Stadskwis: locaties en opdrachten aanpassen</summary><p class="tiny">Vervang locaties door eigen plekken. Dit zijn eigen voorbeeldopdrachten, geen officieel Remunjs kwisboek. points is het maximale puntenaantal; solution (optioneel) is de oplossing die alleen de spelleider ziet.</p><textarea id="taskJSON" class="edit-json" data-draft>${escapeHtml(JSON.stringify(state.task_bank||state.tasks||[],null,2))}</textarea></details><label class="field"><span>Stadskwis: aantal opdrachten</span><select id="setupTaskCount" data-draft name="task_count"><option value="12">12 · ongeveer 1 uur</option><option value="20" selected>20 · ongeveer 2 uur</option><option value="30">30 · een middag</option><option value="0">Alle ${(state.task_bank||state.tasks||[]).length} opdrachten</option></select></label><p class="tiny">De server kiest een gemengde selectie met puzzels, foto- en tekstopdrachten. Bij puzzels ziet alleen de spelleider de oplossing.</p><div class="actions"><button type="submit">Spel klaarzetten</button></div><p class="tiny">Klaarzetten begint een nieuw spel met nul punten. Download zo nodig eerst de bestaande uitslag.</p></form></section>`:''}<section class="panel"><div class="banner">${escapeHtml(state.message)}</div>${state.mode==='city'?`<h2>Stadskwis · ${state.tasks.length} opdrachten</h2><p>Teams verdelen opdrachten over hun subgroepjes en sturen tekst en foto’s in. Punten worden pas na jouw beoordeling toegekend.</p>`:question()}${state.question&&state.phase!=='reveal'&&state.mode!=='wordrace'?`<details><summary>Juiste antwoord · alleen voor de spelleider</summary><p>${escapeHtml(answerText(state.question))}</p></details>`:''}<div class="timer" id="roundTimer"></div>${state.auto?autoHostControls():''}<div class="actions"${state.auto?' hidden':''}>${['lobby','reveal'].includes(state.phase)?button(state.mode==='city'?'Start stadskwis':state.mode==='wordrace'?'Volgende teambeurt':'Volgende vraag','next'):''}${state.phase==='ready'?button('Start over 5 seconden','arm'):''}${state.phase==='paused'?button('Hervatten','resume')+button('Ronde opnieuw','restart_round','',true):''}${['countdown','open','buzzed'].includes(state.phase)?button('Pauzeren','pause','',true):''}${['ready','open','paused','buzzed'].includes(state.phase)&&state.mode!=='city'?button('Antwoord onthullen','reveal','',true):''}${state.phase!=='finished'?button('Spel afronden','finish','',true):button('Terug naar lobby','lobby','',true)}</div>${state.phase==='buzzed'&&!state.auto?`<h2>Als eerste: ${escapeHtml(first?.name)}</h2>${state.buzzes.length>1?'<p class="pending">Vrijwel gelijktijdige drukken (binnen 80 ms). Jij beslist welk team het woord krijgt of herhaal de ronde.</p>':''}${state.buzzes.map(b=>`<div class="actions"><strong>${escapeHtml(b.name)}</strong>${button('Goed +1','judge',`data-id="${b.team_id}" data-correct="true"`)}${button('Fout','judge',`data-id="${b.team_id}" data-correct="false"`,true)}</div>`).join('')}`:''}${state.mode==='quiz'?`<p>${state.answer_count} / ${activeTeams.length} antwoorden ontvangen. Geen bonus voor het snelste antwoord.</p>`:''}</section>${state.mode==='city'?reviewSubmissions():''}${scores()}`;}
function reviewSubmissions(){return `<section class="panel"><h2>Inzendingen beoordelen</h2><p>${state.submissions.length} inzendingen</p>${state.submissions.map(sub=>{const task=state.tasks.find(t=>t.id===sub.task_id);return `<article class="submission"><span class="tag">${escapeHtml(sub.status)}</span><h3>${escapeHtml(sub.team_name)} · ${escapeHtml(task?.title)}</h3>${sub.via_whatsapp?'<p class="pending">WhatsApp-bewijs: controleer de groepschat vóór goedkeuren.</p>':''}<p>${escapeHtml(sub.owner)}</p><p>${escapeHtml(sub.answer)}</p>${task?.solution?`<p class="tiny"><strong>Oplossing:</strong> ${escapeHtml(task.solution)}</p>`:''}${sub.photo_id?button('Bekijk foto','photo',`data-id="${sub.photo_id}"`,true)+`<div id="photo-${sub.photo_id}"></div>`:''}<form class="gradeForm" data-id="${sub.id}"><label class="field"><span>Punten (maximaal ${task?.points})</span><input name="points" type="number" min="0" max="${task?.points}" value="${sub.points}" required></label><label class="field"><span>Feedback</span><input name="note" maxlength="500" value="${escapeHtml(sub.note)}"></label><div class="actions"><button name="approved" value="yes">Goedkeuren / score bewaren</button><button class="secondary" name="approved" value="no">Afwijzen · opnieuw proberen</button></div></form></article>`;}).join('')||'<p>Nog geen inzendingen.</p>'}</section>`;}
function display(){if(state.auto&&state.phase!=='lobby')return `<section class="panel stage auto-stage">${autoScreen()}<div class="timer" id="roundTimer"></div><div class="banner">${escapeHtml(state.message)}</div></section>`;return `<section class="panel stage"><p>${escapeHtml(state.name)}</p>${state.phase==='lobby'?`<h1>Sluit aan en speel mee</h1>${displayJoin?`<div class="display-join">${qr(displayJoin+'/team?code='+state.code)}<div><p>Scan de QR-code met je telefoon, of ga naar</p><p class="linkline">${escapeHtml(displayJoin)}/team</p><p class="code">${state.code}</p></div></div>`:`<p>Scan de QR-code op het spelleiderscherm</p><p class="code">${state.code}</p>`}`:state.mode==='city'?'<h1>Stadskwis</h1><p>Op pad, puzzelen en opdrachten uitvoeren.</p>':question()}<div class="timer" id="roundTimer"></div><div class="banner">${escapeHtml(state.message)}</div>${state.buzzes.length?`<h2>${escapeHtml(state.buzzes.map(b=>b.name).join(' / '))}</h2>`:''}</section>${scores()}`;}
/* 0.15: teams uit 'Mijn groep' van de app (gedeeld door de spelleider) als snelle keuze */
let lanRoster=null;function lanTeams(){if(!lanRoster){lanRoster={players:[]};fetch('/api/groep/namen').then(r=>r.ok?r.json():{players:[]}).then(d=>{lanRoster=d;if(document.querySelector('#joinForm')&&lanTeams().length)render();}).catch(()=>{});}return [...new Set([...(lanRoster.teams||[]),...(lanRoster.players||[]).map(p=>p.team)].filter(Boolean))];}
document.addEventListener('click',e=>{const b=e.target.closest('[data-pickteam]');if(b){const f=document.querySelector('#joinForm');if(f)f.elements.name.value=b.dataset.pickteam;}});
function joinPage(){return `<section class="panel team-help"><h1>Speel mee</h1><p>Zorg dat je telefoon op hetzelfde wifi-netwerk zit als de spelleider.</p><form id="joinForm"><label class="field"><span>Sessiecode</span><input name="code" inputmode="numeric" value="${escapeHtml(new URLSearchParams(location.search).get('code')||state?.code||'')}" pattern="[0-9]{6}" maxlength="6" required></label>${lanTeams().length?`<div class="roster-pick"><span class="tiny">Teams uit jullie groep:</span> ${lanTeams().map(t=>`<button type="button" class="secondary" data-pickteam="${escapeHtml(t)}">${escapeHtml(t)}</button>`).join(' ')}</div>`:''}<label class="field"><span>Nieuwe teamnaam</span><input name="name" maxlength="35" placeholder="Bijvoorbeeld: De Weekendwinnaars"></label><fieldset class="avatar-pick"><legend>Kies jullie personage</legend>${AVATARS.map((a,i)=>`<label><input type="radio" name="avatar" value="${a}" ${i===0?'checked':''}>${avatarImg(a)}</label>`).join('')}</fieldset><label class="field"><span>Of bestaande teamcode</span><input name="access_code" maxlength="6" placeholder="Voor terugkomen of een tweede subgroepje"></label><button type="submit">Meedoen →</button></form></section>`;}
function team(){if(!state?.me)return joinPage();const me=state.me;return `<div class="team-help"><p class="status">${escapeHtml(me.name)} · teamcode ${escapeHtml(me.access_code)}</p><p class="tiny">Met deze teamcode kan een ander subgroepje bij hetzelfde team aansluiten. ${latency===null?'':`Gemeten retourtijd: ${latency} ms.`}</p><div class="banner">${escapeHtml(state.message)}</div>${me.spectator?'<div class="pending">Jullie team kijkt momenteel mee. De spelleider kan jullie weer laten meespelen.</div>':state.mode==='city'?cityTasks():state.mode==='wordrace'?`<section class="panel stage">${wordRace()}<div class="timer" id="roundTimer"></div></section>`:`<section class="panel stage"><div class="timer" id="roundTimer"></div>${state.auto?autoTeam():state.mode==='buzzer'?(me.must_answer?`<h2>Jullie mogen antwoorden!</h2><div class="options answer-buttons auto-answer">${(state.question?.options||[]).map((o,i)=>`<button data-action="answer" data-choice="${i}"><b>${'ABCD'[i]}</b> ${escapeHtml(o)}</button>`).join('')}</div><p class="tiny">Kies binnen 10 seconden.</p>`:state.auto&&['round','standings','finished'].includes(state.phase)?`<section class="auto-stage">${autoStage()}</section>`:`<button class="buzzer" id="buzzButton" data-action="buzz" disabled>BUZZ!</button><p>${state.auto&&me.attempted?'Jullie hebben deze vraag al geprobeerd.':'Kijk naar het grote scherm. Druk pas wanneer de ronde open is.'}</p>`):`<h2>Kijk naar de vraag op het grote scherm</h2>${me.answer!==null&&me.answer!==undefined?`<div class="choice-held">Antwoord ${typeof me.answer==='number'?'ABCD'[me.answer]:escapeHtml(me.answer)} is opgeslagen.</div>`:state.question?.kind==='text'?`<form id="textAnswerForm"><label class="field">Jullie antwoord<input id="textAnswer" data-draft name="text" maxlength="200" autocomplete="off" required></label><button id="sendText" disabled>Antwoord versturen</button></form>`:`<div class="options answer-buttons">${[0,1,2,3].map(i=>`<button data-action="answer" data-choice="${i}" disabled>${'ABCD'[i]}</button>`).join('')}</div><p>Alle teams krijgen dezelfde antwoordtijd.</p>`}`}</section>`}${scores()}</div>`;}
function cityTasks(){return `<section class="panel"><h1>Jullie stadskwis</h1><p>Verdeel de opdrachten. Inzendingen worden eerst op dit apparaat bewaard en bij verbinding naar de spelleider verstuurd.</p>${evidenceCityTeam()}<div class="pending" id="outboxInfo">Wachtrij controleren…</div><div class="actions">${button('Verstuur wachtrij','flush')}${button('Download reservekopie','outbox_export','',true)}${button('Download team-opdrachten','task_export','',true)}</div><p class="tiny">Buiten wifi: houd deze lokale teampagina open. Voor opnieuw openen buiten bereik gebruik je vooraf het team-opdrachtenbestand in de geïnstalleerde PWA via Stadskwis. Je kunt daar antwoorden bewaren en later als bestand inleveren.</p><label class="field"><span>Subgroepje / namen</span><input id="ownerName" data-draft maxlength="50" value="${escapeHtml(localStorage.getItem('groepsspel-subgroup')||'')}" placeholder="Bijvoorbeeld: Joep en Eric"></label><label class="field"><span>Offline antwoordenbestand inleveren</span><input type="file" id="offlineImport" accept="application/json,.json"></label>${state.tasks.map(t=>{const sub=state.submissions.find(s=>s.task_id===t.id),claim=state.claims[t.id];return `<article class="task"><h3>${escapeHtml(t.title)}</h3><span class="tag">${t.points} punten · ${escapeHtml(t.location)}</span><p>${escapeHtml(t.prompt)}</p>${claim?`<p>Opgepakt door: <strong>${escapeHtml(claim)}</strong></p>`:''}<div class="actions">${button('Wij pakken dit op','claim',`data-id="${t.id}"`,true)}${claim?button('Vrijgeven','release',`data-id="${t.id}"`,true):''}</div>${sub?`<div class="banner">${escapeHtml(sub.status)} · ${sub.points} punten ${sub.note?'· '+escapeHtml(sub.note):''}</div>`:''}${!sub||sub.status==='rejected'?`<form class="taskForm" data-id="${t.id}"><label class="field"><span>Jullie antwoord / toelichting</span><textarea id="taskAnswer-${t.id}" data-draft name="answer" maxlength="3000"></textarea></label>${evidenceMode()!=='whatsapp'?`<label class="field"><span>Foto ${t.kind==='photo'?'(verplicht)':'(optioneel)'}</span><input type="file" class="photoInput" data-id="${t.id}" accept="image/*"></label>`:''}${evidenceMode()!=='app'?`<label class="field"><span><input type="checkbox" name="via_whatsapp" value="yes"> Bewijs staat in de WhatsApp-groep</span></label>`:''}<div class="tiny" id="photoInfo-${t.id}"></div><button type="submit">Bewaar inzending</button></form>`:''}</article>`;}).join('')}</section>`;}
function render(){if(role==='host')$('#root').innerHTML=state?host():'<p>Spelleider laden…</p>';else if(role==='display')$('#root').innerHTML=state?display():'<p>Spel laden…</p>';else $('#root').innerHTML=team();if(state?.mode==='city'&&role==='team'&&state.me)refreshOutbox();}
function clock(){if(!state)return;soundTick();const now=Date.now()/1000+offset,opening=state.opens_at-now,active=['countdown','open'].includes(state.phase),live=connected&&active&&opening<=0&&!state.me?.spectator;const text=state.phase==='countdown'&&opening>0?String(Math.ceil(opening)):state.phase==='paused'?'PAUZE':['quiz','wordrace'].includes(state.mode)&&active?Math.max(0,Math.ceil(state.ends_at-now))+' s':live?'GO!':'';const el=$('#roundTimer');if(el)el.textContent=text;const buzz=$('#buzzButton');if(buzz){buzz.disabled=!live||!!state.me?.attempted; buzz.classList.toggle('live',!buzz.disabled);}const textButton=$('#sendText');if(textButton)textButton.disabled=!live;document.querySelectorAll('[data-action="word"]').forEach(b=>b.disabled=!live);if(state.auto){document.querySelectorAll('[data-action="answer"]').forEach(b=>b.disabled=!state.auto.me?.can_answer);const t=autoTimer(now);if(el)el.textContent=t;const fill=$('#autoFill');if(fill){const total=state.phase==='buzzed'?10:state.seconds||20,left=state.phase==='buzzed'?state.auto.answer_until-now:state.ends_at-now;fill.style.width=Math.max(0,Math.min(100,left/total*100))+'%';}}else document.querySelectorAll('[data-action="answer"]').forEach(b=>b.disabled=!live||(state.me?.answer!==null&&state.me?.answer!==undefined));}
function wordRace(){const active=state.teams.find(t=>t.id===state.active_team),words=state.private_words||(state.phase==='reveal'?state.question?.words:null);return `<p class="counter">Halve Minuut · beurt ${state.index+1} · twee beurten per team</p><h2>${escapeHtml(active?.name||'Wacht op de spelleider')}</h2><p>Geef jullie teamtelefoon aan de omschrijver. De rest kijkt naar het grote scherm. Omschrijf zonder het woord zelf te noemen; de omschrijver tikt op goed of pas.</p>${words?words.map((word,i)=>`<div class="wordline"><strong>${escapeHtml(word)}</strong>${state.word_marks[String(i)]?`<span>${state.word_marks[String(i)]==='correct'?'✓ Goed':'↪ Gepast'}</span>`:state.private_words?button('Goed','word',`data-word="${i}" data-mark="correct"`)+button('Pas','word',`data-word="${i}" data-mark="skip"`,true):''}</div>`).join(''):'<div class="pending">Woorden verschijnen alleen op de telefoon van het actieve team zodra de klok start.</div>'}`;}
async function ping(){let samples=[];for(let i=0;i<5;i++){const start=Date.now();const r=await api('/api/ping',null,'');const end=Date.now();samples.push({delay:end-start,offset:r.time-(start+end)/2000});}samples.sort((a,b)=>a.delay-b.delay);latency=samples[2].delay;offset=samples[0].offset;}
async function poll(){if(polling)return;polling=true;try{const next=await api(role==='host'?'/api/host':role==='team'&&teamKey?'/api/team':'/api/public');connected=true;$('#connection').textContent='● Lokale server verbonden';$('#connection').classList.remove('bad');const compare={...next,server_time:0};const before=state;state=next;soundUpdate(before,next);if(signature!==JSON.stringify(compare)){signature=JSON.stringify(compare);preserveRender();}if(role==='team'&&state.me&&state.mode==='city')flush();}catch(err){connected=false;$('#connection').textContent='○ Verbinding weg · gegevens blijven bewaard';$('#connection').classList.add('bad');if(err.status===403&&role==='team'){teamKey='';localStorage.removeItem('groepsspel-lan-team');state=null;render();}}finally{polling=false;}clock();}
async function refreshOutbox(){try{const items=(await outbox('all')).filter(x=>x.session===sessionKey());const el=$('#outboxInfo');if(el)el.textContent=items.length?`${items.length} inzending(en) lokaal bewaard. ${connected?'Wordt verstuurd zodra de stadskwis open is.':'Versturen kan bij terugkeer op wifi.'}`:'Alle lokaal bewaarde inzendingen zijn verstuurd.';}catch{const el=$('#outboxInfo');if(el)el.textContent='Lokale opslag niet beschikbaar. Houd de pagina open en download een reservekopie.';}}
async function flush(){if(flushing||!connected||state?.phase!=='city'||!state.me)return;flushing=true;try{for(const item of (await outbox('all')).filter(x=>x.session===sessionKey())){if(item.blocked)continue;try{await api('/api/submit',item.payload);await outbox('delete',item.key);}catch(err){if(err.status){item.blocked=err.message;await outbox('put',item);note('Inzending vraagt aandacht: '+err.message);}break;}}await refreshOutbox();}finally{flushing=false;}}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function resizePhoto(file){if(file.size>20000000)throw new Error('Kies een foto kleiner dan 20 MB.');const img=new Image(),url=URL.createObjectURL(file);try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Foto kon niet worden geopend.'));img.src=url;});const canvas=document.createElement('canvas'),ratio=Math.min(1,1000/Math.max(img.width,img.height));canvas.width=Math.round(img.width*ratio);canvas.height=Math.round(img.height*ratio);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.65);if(data.length>750000)throw Error('Foto blijft te groot. Kies een kleinere foto.');return data;}finally{URL.revokeObjectURL(url);}}
document.addEventListener('change',async e=>{try{if(e.target.id==='questionsImport'){const file=e.target.files[0];if(!file)return;if(file.size>200000)throw Error('Vragenbestand te groot.');const pack=JSON.parse(await file.text()),questions=Array.isArray(pack)?pack:pack.questions;if(!Array.isArray(questions)||!questions.length)throw Error('Geen vragen gevonden.');$('#questionJSON').value=JSON.stringify(questions,null,2);drafts.questionJSON=$('#questionJSON').value;note(questions.length+' vragen ingelezen. Kies de quizvorm en zet het spel klaar.');}if(e.target.id==='lanAddress'){lanPick=e.target.value;try{localStorage.setItem('groepsspel-lan-address',lanPick);}catch{}const url=e.target.value+'/team?code='+state.code;$('#joinQR').innerHTML=qr(url);$('#joinURL').textContent=url;}if(e.target.classList.contains('photoInput')){const file=e.target.files[0];if(file){photos[e.target.dataset.id]=await resizePhoto(file);$('#photoInfo-'+e.target.dataset.id).textContent='Foto klaar om te bewaren.';}}if(e.target.id==='ownerName')localStorage.setItem('groepsspel-subgroup',e.target.value);if(e.target.id==='offlineImport'){const file=e.target.files[0];if(!file)return;if(file.size>20000000)throw Error('Bestand te groot.');const pack=JSON.parse(await file.text());if(pack.room_id!==state.room_id||pack.team_id!==state.me.id||!Array.isArray(pack.submissions))throw Error('Dit bestand hoort niet bij deze sessie en dit team.');for(const payload of pack.submissions){await outbox('put',{key:sessionKey()+':'+payload.id,session:sessionKey(),payload});}await refreshOutbox();await flush();note('Offline inzendingen ingelezen.');}}catch(err){note(err.message);}});
document.addEventListener('submit',async e=>{e.preventDefault();try{const form=e.target,data=new FormData(form);if(form.id==='joinForm'){const r=await api('/api/join',Object.fromEntries(data),'');teamKey=r.token;localStorage.setItem('groepsspel-lan-team',teamKey);await ping();signature='';await poll();}else if(form.id==='textAnswerForm'){state=await api('/api/answer',{question_id:state.question_id,text:String(data.get('text'))});delete drafts.textAnswer;signature='';preserveRender();}else if(form.id==='setupForm'){const payload={action:'setup',...Object.fromEntries(data),seconds:Number(data.get('seconds')),count:Number(data.get('count')),task_count:Number(data.get('task_count')||0),auto:data.get('mode')==='buzzer'&&data.get('auto')==='1',show:String(data.get('show')||'normaal')};if($('#questionJSON').value.trim())payload.questions=JSON.parse($('#questionJSON').value);payload.tasks=JSON.parse($('#taskJSON').value);await api('/api/action',payload);drafts={};signature='';await poll();}else if(form.classList.contains('gradeForm')){await api('/api/action',{action:'grade',submission_id:form.dataset.id,points:Number(data.get('points')),note:String(data.get('note')),approved:e.submitter?.value==='yes'});signature='';await poll();}else if(form.classList.contains('taskForm')){const taskId=form.dataset.id,owner=$('#ownerName').value.trim();if(!owner)throw Error('Vul eerst de namen van je subgroepje in.');const payload={id:crypto.randomUUID?crypto.randomUUID():randomUUID(),task_id:taskId,answer:String(data.get('answer')),photo:photos[taskId]||'',owner,via_whatsapp:data.get('via_whatsapp')==='yes'};const task=state.tasks.find(t=>t.id===taskId);if(task.kind==='photo'&&!payload.photo&&!payload.via_whatsapp)throw Error('Voeg eerst de foto toe.');if(!payload.answer.trim()&&!payload.photo&&!payload.via_whatsapp)throw Error('Vul een antwoord in.');await outbox('put',{key:sessionKey()+':'+payload.id,session:sessionKey(),payload});photos[taskId]='';form.reset();delete drafts['taskAnswer-'+taskId];note('Inzending veilig op dit apparaat bewaard.');await refreshOutbox();await flush();}}catch(err){note(err.message);}});
function randomUUID(){const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const s=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return s.slice(0,8)+'-'+s.slice(8,12)+'-'+s.slice(12,16)+'-'+s.slice(16,20)+'-'+s.slice(20);}
document.addEventListener('change',e=>{if(e.target.id==='evidenceMode'){drafts.evidenceMode=e.target.value;preserveRender();}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||busy)return;const action=b.dataset.action;try{if(action==='target'||action==='avatar'){busy=true;state=await api('/api/answer',action==='target'?{question_id:state.question_id,target:b.dataset.id}:{question_id:state.question_id,avatar:b.dataset.id});signature='';preserveRender();}else if(['buzz','answer','word'].includes(action)){b.disabled=true;busy=true;state=await api('/api/answer',{question_id:state.question_id,...(action==='answer'?{choice:Number(b.dataset.choice)}:action==='word'?{word:Number(b.dataset.word),mark:b.dataset.mark}:{})});signature='';preserveRender();}else if(action==='flush'){await flush();}else if(action==='outbox_export'){const items=(await outbox('all')).filter(x=>x.session===sessionKey());download('Groepsspel-inzendingen.json',{room_id:state.room_id,team_id:state.me.id,submissions:items.map(x=>x.payload)});}else if(action==='task_export'){download('Groepsspel-team-opdrachten.json',{type:'groepsspel-city-pack',version:1,room_id:state.room_id,team_id:state.me.id,team_name:state.me.name,tasks:state.tasks});}else if(action==='claim'||action==='release'){const owner=$('#ownerName').value.trim();state=await api('/api/claim',{task_id:b.dataset.id,owner,release:action==='release'});signature='';preserveRender();}else if(action==='export'){download('Groepsspel-uitslag.json',await api('/api/export'));}else if(action==='photo'){const response=await fetch('/media/'+b.dataset.id,{headers:{Authorization:'Bearer '+hostKey}});if(!response.ok)throw Error('Foto kon niet worden geopend.');if(photoURLs[b.dataset.id])URL.revokeObjectURL(photoURLs[b.dataset.id]);photoURLs[b.dataset.id]=URL.createObjectURL(await response.blob());const image=document.createElement('img');image.src=photoURLs[b.dataset.id];image.alt='Ingezonden opdrachtfoto';$('#photo-'+b.dataset.id).replaceChildren(image);}else{let payload={action};if(action==='judge')Object.assign(payload,{team_id:b.dataset.id,correct:b.dataset.correct==='true'});if(action==='spectator')Object.assign(payload,{team_id:b.dataset.id,value:b.dataset.value==='true'});if(action==='remove_team')payload.team_id=b.dataset.id;if(action==='score'){const score=prompt('Nieuwe basisscore voor '+b.dataset.name);if(score===null)return;Object.assign(payload,{team_id:b.dataset.id,score:Number(score)});}if(action==='evidence_save'){payload.mode=drafts.evidenceMode ?? evidenceMode();payload.link=drafts.evidenceLink ?? evidenceLink();}
      if(action==='finish'&&!confirm('Spel afronden? De uitslag blijft bewaard.'))return;if(action==='setup')return;await api('/api/action',payload);if(action==='evidence_save'){delete drafts.evidenceMode;delete drafts.evidenceLink;}signature='';await poll();}}catch(err){note(err.message);}finally{busy=false;clock();}});
/* 0.15.4: automatische spelshow (zoals een quizshow op de spelcomputer) met rondesoorten en personages. */
const AVATARS=['lion','fox','panda','frog','monkey','unicorn','octopus','robot','alien','dino','penguin','owl','koala','pig','tiger','cow'];
const AVATAR_NL={lion:'Leeuw',fox:'Vos',panda:'Panda',frog:'Kikker',monkey:'Aap',unicorn:'Eenhoorn',octopus:'Octopus',robot:'Robot',alien:'Ruimtewezen',dino:'Dino',penguin:'Pinguïn',owl:'Uil',koala:'Koala',pig:'Varken',tiger:'Tijger',cow:'Koe'};
function avatarImg(a,cls='av'){return `<img class="${cls}" src="/app/assets/avatars/${AVATARS.includes(a)?a:'lion'}.svg" alt="${escapeHtml(AVATAR_NL[a]||'')}">`;}
const ROUND_RULES={jacht:'Iedereen antwoordt tegelijk op de eigen telefoon. Elk goed antwoord levert 2 punten op.',snel:'Hoe sneller jullie het goede antwoord geven, hoe meer punten: 5, 4, 3, 2 of 1.',buzz:'Druk als eerste op de buzzer en kies dan het antwoord. Goed: 2 punten. Fout: 1 punt eraf en de anderen mogen nog.',taart:'Iedereen antwoordt. Het snelste goede antwoord mag een taart gooien: het geraakte team verliest 2 punten.',roof:'Iedereen antwoordt. Het snelste goede antwoord steelt 2 punten van een team naar keuze.',bom:'Alleen het team met de bom antwoordt. Goed: de bom gaat door naar het volgende team. Wie hem heeft als hij ontploft, verliest 3 punten.',finale:'Snelste goede antwoord: 3 punten, goed: 2 punten, fout: 2 punten eraf, niet geantwoord: 1 punt eraf.'};
const ROUND_ICON={jacht:'🎯',snel:'⚡',buzz:'🔴',taart:'🥧',roof:'🦝',bom:'💣',finale:'🏁'};
const teamById=id=>(state.teams||[]).find(t=>t.id===id);
function autoTimer(now){const a=state.auto;if(a.hold)return 'PAUZE';if(state.phase==='buzzed'&&a.answer_until)return Math.max(0,Math.ceil(a.answer_until-now))+' s';if(state.phase==='open'&&a.mode!=='bomb')return Math.max(0,Math.ceil(state.ends_at-now))+' s';if(state.phase==='countdown')return Math.max(0,Math.ceil(state.opens_at-now))+'';if(state.phase==='pick'&&a.pick)return Math.max(0,Math.ceil(a.pick.until-now))+' s';return '';}
function autoStrip(){const a=state.auto,res=Object.fromEntries((a.results||[]).map(r=>[r.team_id,r])),eff=a.effect||{};
  return `<div class="auto-strip">${(state.teams||[]).filter(t=>!t.spectator).map(t=>{const r=res[t.id],hit=eff.to===t.id&&['pie','steal','boom'].includes(eff.kind)&&['reveal'].includes(state.phase),bomb=a.bomb&&a.bomb.holder===t.id&&!a.bomb.boom;
    return `<div class="auto-team ${r?(r.correct?'ok':'bad'):''} ${a.answered.includes(t.id)?'answered':''} ${hit?'hit-'+eff.kind:''} ${bomb?(a.bomb.hurry?'bomb hurry':'bomb'):''} ${!t.connected?'gone':''}"><div class="auto-av">${avatarImg(t.avatar)}${hit&&eff.kind==='pie'?'<span class="splat">🥧</span>':''}${hit&&eff.kind==='boom'?'<span class="splat">💥</span>':''}${bomb?'<span class="bomb-icon">💣</span>':''}${a.answered.includes(t.id)&&state.phase==='open'?'<span class="tick-mark">✓</span>':''}</div><b translate="no">${escapeHtml(t.name)}</b><span class="auto-score">${t.score}</span>${r&&r.points?`<span class="delta ${r.points>0?'up':'down'}">${r.points>0?'+':''}${r.points}</span>`:''}${hit&&eff.points?`<span class="delta down">−${eff.points}</span>`:''}${eff.from===t.id&&eff.kind==='steal'&&state.phase==='reveal'&&eff.points?`<span class="delta up">+${eff.points}</span>`:''}</div>`;}).join('')}</div>`;}
function autoScreen(){const a=state.auto,q=state.question,ph=state.phase,ranked=[...(state.teams||[])].filter(t=>!t.spectator).sort((x,y)=>y.score-x.score);
  if(ph==='lobby')return `<div class="auto-card"><h1>De show begint zo!</h1><p>${escapeHtml(a.names.join(' → '))}</p>${autoStrip()}</div>`;
  if(ph==='round')return `<div class="auto-card round-card"><p class="counter">Ronde ${a.round} van ${a.rounds}</p><div class="round-icon">${ROUND_ICON[a.type]||'🎲'}</div><h1>${escapeHtml(a.name)}</h1><p class="round-rules">${escapeHtml(ROUND_RULES[a.type]||'')}</p><p class="tiny">${a.questions} vragen</p></div>`;
  if(ph==='standings'||ph==='finished')return `<div class="auto-card"><p class="counter">${ph==='finished'?'Eindstand':'Tussenstand na ronde '+a.round}</p>${ph==='finished'&&ranked[0]?`<div class="winner">${avatarImg(ranked[0].avatar,'av big')}<h1>🏆 <span translate="no">${escapeHtml(ranked[0].name)}</span></h1></div>`:'<h1>Tussenstand</h1>'}<ol class="auto-rank">${ranked.map(t=>`<li>${avatarImg(t.avatar)}<span translate="no">${escapeHtml(t.name)}</span><b>${t.score}</b></li>`).join('')}</ol></div>`;
  const reveal=['reveal','pick'].includes(ph),holder=a.bomb&&teamById(a.bomb.holder);
  return `<div class="auto-q"><p class="counter">${ROUND_ICON[a.type]||''} ${escapeHtml(a.name)} · vraag ${a.question_no} van ${a.questions}</p>${ph==='countdown'||!q?`<h1 class="question">Klaar voor de volgende vraag…</h1>`:`<h1 class="question">${escapeHtml(q.q)}</h1><div class="auto-options">${(q.options||[]).map((o,i)=>`<div class="auto-opt opt-${i} ${reveal&&q.correct===i?'correct':''} ${reveal&&q.correct!==i?'dim':''}"><b>${'ABCD'[i]}</b>${escapeHtml(o)}</div>`).join('')}</div>`}${a.mode!=='bomb'&&['open','buzzed'].includes(ph)?'<div class="auto-bar"><span id="autoFill"></span></div>':''}${a.mode==='bomb'&&holder&&!a.bomb.boom?`<p class="bomb-line ${a.bomb.hurry?'hurry':''}">💣 <span translate="no">${escapeHtml(holder.name)}</span> heeft de bom!</p>`:''}${ph==='buzzed'&&state.buzzes[0]?`<p class="buzz-line">🔴 <span translate="no">${escapeHtml(state.buzzes[0].name)}</span> drukte als eerste!</p>`:''}${ph==='pick'&&a.pick?`<p class="buzz-line">${a.pick.kind==='pie'?'🥧':'🦝'} <span translate="no">${escapeHtml(teamById(a.pick.team_id)?.name||'')}</span> ${a.pick.kind==='pie'?'kiest wie de taart krijgt…':'kiest van wie ze punten stelen…'}</p>`:''}</div>${autoStrip()}`;}
function autoTeam(){const a=state.auto,me=state.me,mine=a.me||{},ph=state.phase,q=state.question,res=(a.results||[]).find(r=>r.team_id===me.id);
  const opts=()=>`<div class="auto-answers">${(q?.options||[]).map((o,i)=>`<button class="auto-opt opt-${i}" data-action="answer" data-choice="${i}"><b>${'ABCD'[i]}</b><span>${escapeHtml(o)}</span></button>`).join('')}</div>`;
  let body='';
  if(['lobby','finished'].includes(ph))body=`${ph==='finished'?autoScreen():''}<h2>Jullie personage</h2><div class="avatar-pick small">${AVATARS.map(x=>`<button type="button" class="${me.avatar===x?'chosen':''}" data-action="avatar" data-id="${x}">${avatarImg(x)}</button>`).join('')}</div>`;
  else if(['round','standings'].includes(ph))body=autoScreen();
  else if(ph==='countdown')body=`<h2>Let op, de vraag komt eraan…</h2><p class="tiny">${escapeHtml(ROUND_RULES[a.type]||'')}</p>`;
  else if(ph==='pick')body=mine.must_pick?`<h2>${mine.must_pick==='pie'?'🥧 Naar wie gooien jullie de taart?':'🦝 Van wie stelen jullie 2 punten?'}</h2><div class="avatar-pick targets">${(state.teams||[]).filter(t=>!t.spectator&&t.id!==me.id).map(t=>`<button type="button" data-action="target" data-id="${t.id}">${avatarImg(t.avatar)}<span translate="no">${escapeHtml(t.name)}</span><small>${t.score}</small></button>`).join('')}</div>`:`<h2>${a.pick?.kind==='pie'?'🥧 Er vliegt zo een taart…':'🦝 Er worden punten gestolen…'}</h2>`;
  else if(ph==='reveal')body=res?`<div class="auto-result ${res.correct?'ok':'bad'}">${res.correct?'✓ Goed!':'✗ Helaas'}${res.points?` <b>${res.points>0?'+':''}${res.points}</b>`:''}</div>`:`<h2>${a.effect?.kind==='boom'&&a.effect.to===me.id?'💥 BOEM! De bom ontplofte bij jullie.':a.effect?.kind==='pie'&&a.effect.to===me.id?'🥧 Pats! Jullie kregen de taart.':'Kijk naar het grote scherm'}</h2>`;
  else if(a.mode==='buzz')body=mine.can_answer?`<h2>Jullie mogen antwoorden!</h2>${opts()}`:`<button class="buzzer" id="buzzButton" data-action="buzz" disabled>BUZZ!</button><p>${me.attempted?'Jullie hebben deze vraag al geprobeerd.':'Druk zodra de vraag open is.'}</p>`;
  else if(a.mode==='bomb')body=mine.can_answer?`<h2 class="bomb-line">💣 Jullie hebben de bom! Snel antwoorden!</h2>${opts()}`:`<h2>💣 <span translate="no">${escapeHtml(teamById(a.bomb?.holder)?.name||'')}</span> heeft de bom.</h2>`;
  else body=mine.can_answer?`${opts()}<p class="tiny">${escapeHtml(ROUND_RULES[a.type]||'')}</p>`:`<h2>Antwoord gekozen!</h2><p>Wachten op de andere teams…</p>`;
  return `<div class="auto-me">${avatarImg(me.avatar)}<span translate="no">${escapeHtml(me.name)}</span><b>${me.score}</b></div>${body}`;}
function autoHostControls(){const p=state.phase,a=state.auto;return `<div class="pending">Automatische show · ${escapeHtml(a.names.join(' → '))}. Het spel stelt de vragen en telt de punten. Zet de beamerweergave op de tv.</div><div class="actions">${p==='lobby'?button('▶ Start de show','next'):''}${!['lobby','finished'].includes(p)?(a.hold||p==='paused'?button('Hervatten','resume'):button('Pauzeren','pause','',true)):''}${['open','buzzed'].includes(p)?button('Vraag overslaan','reveal','',true):''}${p!=='finished'?button('Spel afronden','finish','',true):button('Terug naar lobby','lobby','',true)}</div>`;}
/* 0.15.4: geluid en muziek op het spelleider- en beamerscherm (niet op teamtelefoons). Knop rechtsonder, per scherm onthouden. */
const soundScreen=(role==='host'||role==='display')&&typeof GSound!=='undefined';let lastTick=-1;
function soundUpdate(prev,next){if(!soundScreen||!next)return;if(next.auto){autoShowEvents(prev,next);return;}if(typeof GPresenter!=='undefined')GPresenter.hide();const p=prev?.phase,n=next.phase,city=next.mode==='city';
  GSound.bed(city?null:n==='lobby'||(n==='ready'&&!next.question)?'lobby':['ready','countdown','open'].includes(n)?'quiz':n==='reveal'?'lobby':n==='finished'?'finale':null);
  if(!prev||prev.code!==next.code)return;
  if(n==='countdown'&&p!=='countdown')GSound.play('intro');
  if(n==='buzzed'&&p!=='buzzed')GSound.play('buzz');
  else if((next.buzzes||[]).length>(prev.buzzes||[]).length&&n==='buzzed')GSound.play('buzz');
  if(n==='reveal'&&p!=='reveal'){const gain=(next.teams||[]).some(t=>{const o=(prev.teams||[]).find(x=>x.id===t.id);return o&&t.score>o.score;});GSound.play(gain?'correct':'wrong');}
  if(p==='buzzed'&&n==='ready')GSound.play('wrong');
  if(n==='finished'&&p!=='finished')GSound.play('end');}
let bombTick=0;function soundTick(){if(!soundScreen||!GSound.enabled())return;const now=Date.now()/1000+offset;if(state.auto?.mode==='bomb'&&state.phase==='open'&&!state.auto.bomb?.boom){const gap=state.auto.bomb?.hurry?.4:1;if(now-bombTick>=gap){bombTick=now;GSound.play('tick');}return;}let left=-1;if(state.phase==='open'&&['quiz','wordrace'].includes(state.mode)&&state.ends_at>now&&state.ends_at-now<=5)left=Math.ceil(state.ends_at-now);if(left>0&&left!==lastTick){lastTick=left;GSound.play('tick');}if(left<=0)lastTick=-1;}
/* 0.15.4: gebeurtenissen van de automatische show: muziek, effecten en presentator Joep. */
const pick=list=>list[Math.floor(Math.random()*list.length)];
function autoShowEvents(prev,next){const a=next.auto,n=next.phase,p=prev?.phase,pa=prev?.auto,P=typeof GPresenter!=='undefined'?GPresenter:null,name=id=>(next.teams||[]).find(t=>t.id===id)?.name||'';
  if(P){GPresenter.mount({small:role==='host'});if(n!=='lobby')GPresenter.show(true);}
  GSound.bed(n==='lobby'||n==='round'||n==='standings'?'lobby':n==='finished'?'finale':a.mode==='bomb'?'mystery':['countdown','open','buzzed','pick','reveal','paused'].includes(n)?'quiz':null);
  if(!prev||prev.code!==next.code||(p===n&&pa?.question_no===a.question_no&&JSON.stringify(pa?.effect)===JSON.stringify(a.effect)&&(prev.buzzes||[]).length===(next.buzzes||[]).length))return;
  const say=(t,o)=>P&&GPresenter.say(t,o);
  if(n==='round'&&p!=='round'){GSound.play('whoosh');GSound.play('intro');if(a.round===1)say(`Goedenavond en welkom bij de show! Ik ben Joep, jullie presentator.`,{mood:'wave'});say(`Ronde ${a.round}: ${a.name}!`,{mood:'point',queue:a.round===1});say(ROUND_RULES[a.type]||'',{queue:true});}
  if(n==='open'&&p==='countdown'&&next.question){if(a.mode==='bomb'&&a.bomb)say(`${name(a.bomb.holder)} heeft de bom!`,{mood:'point'});say(next.question.q,{bubble:`Vraag ${a.question_no}!`,mood:'point',queue:a.mode==='bomb'});}
  if(n==='buzzed'&&p!=='buzzed'&&next.buzzes[0]){GSound.play('buzz');say(pick([`${next.buzzes[0].name} drukt als eerste!`,`Daar is ${next.buzzes[0].name}! Wat wordt het?`,`${next.buzzes[0].name} was het snelst!`]),{mood:'point'});}
  if(n==='pick'&&p!=='pick'&&a.pick){GSound.play('correct');say(a.pick.kind==='pie'?`${name(a.pick.team_id)} mag een taart gooien! Naar wie gaat hij?`:`${name(a.pick.team_id)} mag twee punten stelen! Van wie?`,{mood:'happy'});}
  if(n==='reveal'&&(p!=='reveal'||JSON.stringify(pa?.effect)!==JSON.stringify(a.effect))){const e=a.effect,res=a.results||[],good=res.filter(r=>r.correct),ans=next.question&&next.question.options?next.question.options[next.question.correct]:'';
    if(e?.kind==='boom'){GSound.play('boom');say(`BOEM! De bom ontploft bij ${name(e.to)}. Dat kost drie punten!`,{mood:'sad'});}
    else if(e?.kind==='pie'){GSound.play('splat');say(pick([`Pats! Een taart vol in het gezicht van ${name(e.to)}!`,`Raak! ${name(e.to)} zit onder de slagroom!`]),{mood:'happy'});}
    else if(e?.kind==='steal'){GSound.play('pass');say(`${name(e.from)} steelt punten van ${name(e.to)}!`,{mood:'happy'});}
    else if(a.mode==='bomb'){GSound.play(good.length?'correct':'wrong');}
    else if(good.length){GSound.play('correct');say(good.length===1?pick([`Helemaal goed, ${name(good[0].team_id)}!`,`Knap gedaan, ${name(good[0].team_id)}!`]):pick([`Goed gedaan! Het antwoord was ${ans}.`,`Ja! ${ans} is het juiste antwoord.`]),{mood:'happy'});}
    else{GSound.play('wrong');say(ans?`Helaas, niemand had het goed. Het juiste antwoord was ${ans}.`:`Helaas, niemand had het goed.`,{mood:'sad'});}}
  if(a.mode==='buzz'&&p==='buzzed'&&n==='open'){GSound.play('wrong');say(pick([`Oei, dat klopt niet! De anderen mogen nog.`,`Helaas! Wie durft er nog?`]),{mood:'sad'});}
  if(n==='standings'&&p!=='standings'){const top=[...next.teams].filter(t=>!t.spectator).sort((x,y)=>y.score-x.score);GSound.play('whoosh');if(top[0])say(top[1]&&top[1].score===top[0].score?`Even de tussenstand. ${top[0].name} en ${top[1].name} staan gelijk bovenaan!`:`Even de tussenstand. ${top[0].name} staat bovenaan!`,{mood:'point'});}
  if(n==='finished'&&p!=='finished'){const top=[...next.teams].filter(t=>!t.spectator).sort((x,y)=>y.score-x.score);GSound.play('end');if(top[0])say(top[1]&&top[1].score===top[0].score?`Wat een spanning! Het is gelijkspel tussen ${top[0].name} en ${top[1].name}!`:`En de winnaar is ${top[0].name}! Gefeliciteerd!`,{mood:'happy'});}}
if(soundScreen)GSound.mount();
let displayJoin='';if(role==='display')fetch('/api/lan').then(r=>r.json()).then(v=>{let pick='';try{pick=localStorage.getItem('groepsspel-lan-address')||'';}catch{}displayJoin=(v.urls||[]).includes(pick)?pick:(v.urls||[])[0]||'';signature='';}).catch(()=>{});
(async()=>{try{if(role==='host'){const r=await api('/api/bootstrap',null,'');hostKey=r.host_key;urls=r.urls;}await ping();await poll();setInterval(poll,500);setInterval(clock,80);}catch(err){$('#root').innerHTML=`<section class="panel"><h1>Verbinding niet beschikbaar</h1><p>${escapeHtml(err.message)}</p><p>Open de spelleider op de server-pc via http://127.0.0.1:8765/host. Laat de server actief en verbind teamtelefoons met dezelfde wifi.</p></section>`;}})();
